--- /dev/null
+++ b/test/js/saved.test.mjs
@@ -0,0 +1,166 @@
+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import vm from 'node:vm';
+import { repoFile } from './load.mjs';
+
+class Element {
+  children = []; listeners = {}; className = ''; hidden = false; disabled = false; value = ''; content = '';
+  classList = {
+    add: (name) => { this.className += ` ${name}`; },
+    remove: (name) => { this.className = this.className.split(' ').filter((c) => c !== name).join(' '); },
+  };
+  set textContent(value) { this.content = value; this.children = []; }
+  get textContent() { return this.content + this.children.map((c) => c.textContent).join(''); }
+  set innerHTML(value) { this.textContent = value; }
+  get innerHTML() { return this.textContent; }
+  append(...children) { this.children.push(...children); }
+  replaceChildren(...children) { this.content = ''; this.children = children; }
+  addEventListener(type, listener) { this.listeners[type] = listener; }
+  querySelectorAll() { return this.children.filter((c) => c.className.includes(' active')); }
+  // Dispatch even hidden/disabled actions to verify the handler's state guard too.
+  fire(type = 'click') { return this.listeners[type]?.(); }
+}
+const detail = (id) => ({ id, db_seq: id + 10, db_name: `DB${id}`, sql: `SELECT ${id}`, row_count: 1, columns: [{ name: 'n', type: 'INT' }], rows: [{ n: id }] });
+const tick = () => new Promise((resolve) => setImmediate(resolve));
+async function page() {
+  const elements = new Map();
+  const el = (name) => {
+    const selector = name.startsWith('#') ? name : `#saved-${name}`;
+    if (!elements.has(selector)) elements.set(selector, new Element());
+    return elements.get(selector);
+  };
+  const requests = [], copies = [], notices = [], storage = new Map();
+  const window = { confirm: () => true, location: { href: '/saved' } };
+  const context = vm.createContext({
+    document: { querySelector: el, createElement: () => new Element() }, window,
+    sessionStorage: { setItem: (key, value) => storage.set(key, value) },
+    api: (url, options = {}) => new Promise((resolve, reject) => requests.push({ url, method: options.method || 'GET', resolve, reject })),
+    initLayout: () => Promise.resolve(), fmtDate: () => '', highlightSQL: (sql) => sql,
+    toast: (...args) => notices.push(args), copyText: (text) => copies.push(text),
+    setTimeout, clearTimeout,
+  });
+  // Only replace imports; run the production initialization and event listeners unchanged.
+  vm.runInContext(repoFile('internal/webui/js/saved.js').replace(/^import .*;\n/gm, ''), context);
+  await tick();
+  requests.shift().resolve({ items: [detail(1), detail(2)] });
+  await tick();
+  const select = (id) => el('list').children.find((c) => c.textContent.startsWith(`#${id} ·`)).fire();
+  const request = (id, method = 'GET') => requests.findLast((r) => r.url.endsWith(`/${id}`) && r.method === method);
+  const ready = async (id) => { select(id); request(id).resolve(detail(id)); await tick(); };
+  const current = () => vm.runInContext('current', context);
+  return { el, requests, copies, notices, storage, window, select, request, ready, current };
+}
+function assertReady(p, id) {
+  assert.equal(p.current()?.id, id);
+  assert.match(p.el('title').textContent, new RegExp(`결과 #${id} ·`));
+  assert.equal(p.el('#saved-sql > code').innerHTML, `SELECT ${id}`);
+  assert.equal(p.el('sql').hidden, false);
+  assert.match(p.el('result').textContent, new RegExp(`${id}$`));
+  assert.deepEqual(p.el('list').querySelectorAll().map((c) => c.children[0].textContent), [`#${id} · DB${id}`]);
+  for (const name of ['tsv', 'open', 'delete']) assert.equal(p.el(name).hidden, false);
+}
+async function assertBlocked(p) {
+  assert.equal(p.current(), null);
+  assert.equal(p.el('sql').hidden, true);
+  assert.equal(p.el('#saved-sql > code').innerHTML, '');
+  for (const name of ['tsv', 'open', 'delete']) {
+    assert.equal(p.el(name).hidden, true);
+    await p.el(name).fire();
+  }
+  assert.equal(p.copies.length, 0);
+  assert.equal(p.storage.size, 0);
+  assert.equal(p.window.location.href, '/saved');
+  assert.equal(p.requests.filter((r) => r.method === 'DELETE').length, 0);
+}
+
+test('selection clears old SQL, table and actions during loading and failure', async () => {
+  const p = await page(); await p.ready(1); p.select(2);
+  await assertBlocked(p);
+  assert.equal(p.el('result').children.length, 0);
+  p.request(2).reject(new Error('조회 실패')); await tick();
+  await assertBlocked(p);
+  assert.match(p.el('title').textContent, /#2.*실패/);
+  assert.equal(p.el('result').textContent, '조회 실패');
+  await p.ready(2); assertReady(p, 2);
+  p.el('tsv').fire(); p.el('open').fire();
+  assert.deepEqual(p.copies, ['n\n2']);
+  assert.equal(p.storage.get('dartfly.pendingSQL'), 'SELECT 2');
+  assert.equal(p.storage.get('dartfly.pendingDB'), '12');
+});
+for (const late of ['success', 'failure']) {
+  test(`late ${late} cannot replace the latest detail`, async () => {
+    const p = await page(); p.select(1); const old = p.request(1);
+    await p.ready(2);
+    if (late === 'success') old.resolve(detail(1)); else old.reject(new Error('old failure'));
+    await tick(); assertReady(p, 2);
+  });
+}
+test('same ID selected twice still ignores the earlier response', async () => {
+  const p = await page(); p.select(1); const old = p.request(1);
+  await p.ready(1); old.resolve({ ...detail(1), sql: 'stale' });
+  await tick(); assertReady(p, 1);
+});
+for (const loaded of [false, true]) {
+  test(`delete fixes its ID, blocks duplicates and preserves B (${loaded ? 'ready' : 'loading'})`, async () => {
+    const p = await page(); await p.ready(1);
+    const deleting = p.el('delete').fire();
+    assert.equal(p.el('delete').disabled, true);
+    await p.el('delete').fire();
+    p.select(2);
+    if (loaded) { p.request(2).resolve(detail(2)); await tick(); }
+    assert.equal(p.requests.filter((r) => r.method === 'DELETE').length, 1);
+    p.request(1, 'DELETE').resolve({}); await tick();
+    const refresh = p.requests.findLast((r) => r.url.includes('?limit='));
+    refresh.resolve({ items: [detail(2)] }); await deleting;
+    if (!loaded) { p.request(2).resolve(detail(2)); await tick(); }
+    assertReady(p, 2); assert.equal(p.el('delete').disabled, false);
+  });
+}
+test('deleting A invalidates an in-flight re-selection of A', async () => {
+  const p = await page(); await p.ready(1);
+  const deleting = p.el('delete').fire();
+  p.select(1); const late = p.request(1);
+  p.request(1, 'DELETE').resolve({}); await tick();
+  late.resolve(detail(1)); await tick();
+  p.requests.findLast((r) => r.url.includes('?limit=')).resolve({ items: [detail(2)] });
+  await deleting;
+  assert.equal(p.current(), null); assert.equal(p.el('delete').hidden, true);
+  assert.equal(p.el('result').textContent, '-');
+});
+test('delete failure re-enables retry without clearing the current detail', async () => {
+  const p = await page(); await p.ready(1);
+  const deleting = p.el('delete').fire(); p.request(1, 'DELETE').reject(new Error('삭제 실패'));
+  await deleting; assertReady(p, 1); assert.equal(p.el('delete').disabled, false);
+  assert.deepEqual(p.notices.at(-1), ['삭제 실패', true]);
+});
+test('successful deletion clears A and removes its card before list refresh', async () => {
+  const p = await page(); await p.ready(1);
+  const deleting = p.el('delete').fire();
+  p.request(1, 'DELETE').resolve({}); await tick();
+  assert.equal(p.current(), null);
+  assert.equal(p.el('sql').hidden, true);
+  assert.equal(p.el('delete').hidden, true);
+  assert.equal(p.el('list').children.length, 1);
+  assert.equal(p.el('list').querySelectorAll().length, 0);
+  p.requests.findLast((r) => r.url.includes('?limit=')).resolve({ items: [detail(2)] });
+  await deleting;
+});
+test('delete failure preserves a later selection and allows deleting its own ID', async () => {
+  const p = await page(); await p.ready(1);
+  const deleting = p.el('delete').fire(); await p.ready(2);
+  await p.el('delete').fire();
+  assert.equal(p.requests.filter((r) => r.method === 'DELETE').length, 1);
+  p.request(1, 'DELETE').reject(new Error('삭제 실패')); await deleting;
+  assertReady(p, 2);
+  const retry = p.el('delete').fire();
+  assert.ok(p.request(2, 'DELETE'));
+  p.request(2, 'DELETE').reject(new Error('retry failed')); await retry;
+});
+test('late success cannot revive A after the latest selection failed', async () => {
+  const p = await page(); p.select(1); const old = p.request(1);
+  p.select(2); p.request(2).reject(new Error('B failed')); await tick();
+  old.resolve(detail(1)); await tick();
+  await assertBlocked(p);
+  assert.equal(p.el('result').textContent, 'B failed');
+  assert.match(p.el('title').textContent, /#2.*실패/);
+});
commit 5cd5ca08d2c99f95f9e31f33cc3e4a4ddbc1c678
Author: hkjang <gagagiga@naver.com>
Date:   Sun Sep 20 19:05:50 2026 +0900

    fix: 저장 결과 상세의 늦은 응답과 삭제 경합 방지

import { api, initLayout, toast, fmtDate, copyText } from '/js/layout.js';
import { highlightSQL } from '/js/sqlhighlight.js';

const list = document.querySelector('#saved-list');
const search = document.querySelector('#saved-search');
const titleEl = document.querySelector('#saved-title');
const sqlEl = document.querySelector('#saved-sql');
const sqlCode = document.querySelector('#saved-sql > code');
const resultEl = document.querySelector('#saved-result');
const tsvBtn = document.querySelector('#saved-tsv');
const openBtn = document.querySelector('#saved-open');
const deleteBtn = document.querySelector('#saved-delete');
let items = [];
let current = null;
let selectedID = null;
let detailRequest = 0;
let deleting = false;
let debounce = null;

async function loadList() {
  try {
    const page = await api('/api/v1/query/saved?limit=200');
    items = page.items || [];
    renderList();
  } catch (cause) { list.className = 'empty'; list.textContent = cause.message; }
}

function renderList() {
  const term = search.value.trim().toLowerCase();
  const filtered = items.filter((s) => !term || (s.sql || '').toLowerCase().includes(term) || (s.db_name || '').toLowerCase().includes(term));
  document.querySelector('#saved-count').textContent = `${filtered.length}건`;
  if (!filtered.length) { list.className = 'empty'; list.textContent = '저장된 결과가 없습니다.'; return; }
  list.className = 'resource-list';
  list.replaceChildren(...filtered.map((s) => {
    const btn = document.createElement('button');
    btn.type = 'button'; btn.className = 'resource-card' + (selectedID === s.id ? ' active' : '');
    const top = document.createElement('div'); top.className = 'rc-top';
    const name = document.createElement('strong'); name.textContent = `#${s.id} · ${s.db_name || 'DB#' + s.db_seq}`;
    top.append(name);
    const meta = document.createElement('span'); meta.className = 'rc-meta'; meta.textContent = `${s.row_count}행 · ${s.user_name || ''} · ${fmtDate(s.created_at)}`;
    const desc = document.createElement('span'); desc.className = 'rc-desc'; desc.textContent = s.sql;
    btn.append(top, meta, desc);
    btn.addEventListener('click', () => showDetail(s.id));
    return btn;
  }));
}

function clearDetail() {
  current = null;
  sqlEl.hidden = true; sqlCode.innerHTML = '';
  tsvBtn.hidden = openBtn.hidden = deleteBtn.hidden = true;
  resultEl.className = 'empty'; resultEl.textContent = '-';
}

async function showDetail(id) {
  const request = ++detailRequest;
  selectedID = id;
  clearDetail();
  renderList();
  titleEl.textContent = `결과 #${id} 불러오는 중...`;
  try {
    const d = await api(`/api/v1/query/saved/${id}`);
    if (request !== detailRequest) return;
    current = d;
    titleEl.textContent = `결과 #${d.id} · ${d.db_name || 'DB#' + d.db_seq} · ${d.row_count}행`;
    sqlEl.hidden = false; sqlCode.innerHTML = highlightSQL(d.sql || '');
    tsvBtn.hidden = false; openBtn.hidden = false; deleteBtn.hidden = false;
    renderResult(d);
  } catch (cause) {
    if (request !== detailRequest) return;
    clearDetail();
    titleEl.textContent = `결과 #${id} 불러오기 실패`;
    resultEl.textContent = cause.message;
  }
}

function renderResult(d) {
  if (!d.columns || !d.columns.length) { resultEl.className = 'empty'; resultEl.textContent = '저장된 컬럼이 없습니다.'; return; }
  resultEl.className = 'query-grid-wrap';
  const table = document.createElement('table');
  const head = document.createElement('thead'); const hr = document.createElement('tr');
  const idxTh = document.createElement('th'); idxTh.className = 'row-idx'; idxTh.textContent = '#'; hr.append(idxTh);
  d.columns.forEach((c) => { const th = document.createElement('th'); th.textContent = c.name; th.title = c.type; hr.append(th); });
  head.append(hr);
  const body = document.createElement('tbody');
  (d.rows || []).forEach((row, i) => {
    const tr = document.createElement('tr');
    const idx = document.createElement('td'); idx.className = 'row-idx'; idx.textContent = String(i + 1); tr.append(idx);
    d.columns.forEach((c) => { const td = document.createElement('td'); const v = row[c.name]; if (v === null || v === undefined) { td.textContent = 'NULL'; td.className = 'null-value'; } else td.textContent = String(v); tr.append(td); });
    body.append(tr);
  });
  table.append(head, body);
  resultEl.replaceChildren(table);
}

tsvBtn.addEventListener('click', () => {
  if (!current) return;
  const cols = current.columns.map((c) => c.name);
  const lines = [cols.join('\t'), ...(current.rows || []).map((r) => cols.map((c) => { const v = r[c]; return v == null ? '' : String(v).replace(/[\t\n\r]/g, ' '); }).join('\t'))];
  copyText(lines.join('\n'), 'TSV로 복사했습니다.');
});
openBtn.addEventListener('click', () => {
  if (!current) return;
  sessionStorage.setItem('dartfly.pendingSQL', current.sql || '');
  if (current.db_seq) sessionStorage.setItem('dartfly.pendingDB', String(current.db_seq));
  window.location.href = '/';
});
deleteBtn.addEventListener('click', async () => {
  if (!current || deleting) return;
  const id = current.id;
  if (!window.confirm(`저장 결과 #${id}을(를) 삭제할까요?`)) return;
  deleting = true; deleteBtn.disabled = true;
  try {
    await api(`/api/v1/query/saved/${id}`, { method: 'DELETE' });
    toast('삭제했습니다.');
    if (selectedID === id) {
      // 삭제 전에 시작한 같은 결과의 조회도 더 이상 상세를 복구할 수 없습니다.
      ++detailRequest;
      selectedID = null;
      clearDetail();
      titleEl.textContent = '결과를 선택하세요';
    }
    items = items.filter((s) => s.id !== id);
    renderList();
    await loadList();
  } catch (cause) { toast(cause.message, true); }
  finally { deleting = false; deleteBtn.disabled = false; }
});
search.addEventListener('input', () => { clearTimeout(debounce); debounce = setTimeout(renderList, 200); });

initLayout('/saved').then(loadList).catch((cause) => { list.className = 'empty'; list.textContent = cause.message; });
package server

import (
	"net/http"
	"strconv"

	"github.com/hkjang/dartfly/internal/query"
)

func resultsaveSession(w http.ResponseWriter, r *http.Request, options Options) (int64, bool, bool) {
	session, ok := authenticatedSession(r, options)
	if !ok {
		writeProblem(w, r, http.StatusUnauthorized, "DF_AUTH_REQUIRED", "로그인이 필요합니다")
		return 0, false, false
	}
	if options.ResultSave == nil {
		writeProblem(w, r, http.StatusServiceUnavailable, "DF_SYSTEM_MASTER_KEY_UNAVAILABLE", "결과 저장 서비스가 구성되지 않았습니다(Master Key 필요)")
		return 0, false, false
	}
	return session.User.Seq, isManager(session.User.Role), true
}

func saveResultHandler(options Options) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, admin, ok := resultsaveSession(w, r, options)
		if !ok {
			return
		}
		var input struct {
			DBSeq      int64          `json:"db_seq"`
			SQL        string         `json:"sql"`
			Parameters map[string]any `json:"parameters"`
			MaxRows    int            `json:"max_rows"`
		}
		if err := decodeJSON(w, r, &input); err != nil || input.DBSeq <= 0 {
			writeProblem(w, r, http.StatusBadRequest, "DF_SQL_INVALID_REQUEST", "결과 저장 요청 형식이 올바르지 않습니다")
			return
		}
		maxRows := input.MaxRows
		if maxRows <= 0 || maxRows > options.MaxRows {
			maxRows = options.MaxRows
		}
		ids := requestIDsFrom(r.Context())
		saved, err := options.ResultSave.Save(r.Context(), input.DBSeq, userID, admin, input.SQL, query.Options{
			MaxRows: maxRows, Timeout: options.QueryTimeout, AuditID: ids.AuditID, TraceID: ids.TraceID,
			ActorID: strconv.FormatInt(userID, 10), ClientIP: clientIP(r), ServerBind: true, NamedParams: input.Parameters,
		})
		if err != nil {
			writeExecutionProblem(w, r, err)
			return
		}
		writeSuccessStatus(w, r, http.StatusCreated, saved)
	}
}

func listSavedResultsHandler(options Options) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, admin, ok := resultsaveSession(w, r, options)
		if !ok {
			return
		}
		limit, offset := 100, 0
		if v := r.URL.Query().Get("limit"); v != "" {
			if p, err := strconv.Atoi(v); err == nil {
				limit = p
			}
		}
		if v := r.URL.Query().Get("offset"); v != "" {
			if p, err := strconv.Atoi(v); err == nil {
				offset = p
			}
		}
		page, err := options.ResultSave.List(r.Context(), userID, admin, limit, offset)
		if err != nil {
			writeProblem(w, r, http.StatusInternalServerError, "DF_SAVE_LIST_FAILED", "저장된 결과를 조회할 수 없습니다")
			return
		}
		writeSuccess(w, r, page)
	}
}

func getSavedResultHandler(options Options) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, admin, ok := resultsaveSession(w, r, options)
		if !ok {
			return
		}
		id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
		if err != nil {
			writeProblem(w, r, http.StatusBadRequest, "DF_SAVE_INVALID_REQUEST", "결과 ID가 올바르지 않습니다")
			return
		}
		detail, err := options.ResultSave.Get(r.Context(), id, userID, admin)
		if err != nil {
			writeProblem(w, r, http.StatusNotFound, "DF_SAVE_NOT_FOUND", err.Error())
			return
		}
		writeSuccess(w, r, detail)
	}
}

func deleteSavedResultHandler(options Options) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, admin, ok := resultsaveSession(w, r, options)
		if !ok {
			return
		}
		id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
		if err != nil {
			writeProblem(w, r, http.StatusBadRequest, "DF_SAVE_INVALID_REQUEST", "결과 ID가 올바르지 않습니다")
			return
		}
		if err := options.ResultSave.Delete(r.Context(), id, userID, admin); err != nil {
			writeProblem(w, r, http.StatusBadRequest, "DF_SAVE_DELETE_FAILED", err.Error())
			return
		}
		writeSuccess(w, r, map[string]bool{"deleted": true})
	}
}
// Package resultsave는 쿼리 실행 결과 세트를 저장하고 재조회하는 기능을 제공합니다.
// executed_sql_resource(result_save_yn='YES', types='SAVE')에 메타를, executed_sql_result_data에
// 결과 JSON을 보관합니다. 감사/증빙 목적으로 결과를 보존할 수 있습니다.
package resultsave

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/hkjang/dartfly/internal/query"
)

// Saved는 저장된 결과의 메타데이터입니다.
type Saved struct {
	ID        int64     `json:"id"`
	DBSeq     int64     `json:"db_seq"`
	DBName    string    `json:"db_name"`
	UserSeq   int64     `json:"user_seq"`
	UserName  string    `json:"user_name"`
	SQL       string    `json:"sql"`
	RowCount  int       `json:"row_count"`
	CreatedAt time.Time `json:"created_at"`
}

// SavedPage는 페이지네이션된 저장 결과 목록입니다.
type SavedPage struct {
	Items  []Saved `json:"items"`
	Total  int64   `json:"total"`
	Limit  int     `json:"limit"`
	Offset int     `json:"offset"`
}

// Detail은 저장된 결과 본문(컬럼+행)입니다.
type Detail struct {
	Saved
	Columns []query.Column   `json:"columns"`
	Rows    []map[string]any `json:"rows"`
}

type storedResult struct {
	Columns []query.Column   `json:"columns"`
	Rows    []map[string]any `json:"rows"`
}

type Repository interface {
	InsertSavedResult(ctx context.Context, userID, dbSeq int64, sqlText, resultJSON string, rowCount int) (Saved, error)
	ListSavedResults(ctx context.Context, userID int64, admin bool, limit, offset int) ([]Saved, int64, error)
	GetSavedResult(ctx context.Context, id, userID int64, admin bool) (Saved, string, error)
	DeleteSavedResult(ctx context.Context, id, userID int64, admin bool) error
}

type Service struct {
	repository Repository
	executor   *query.Executor
}

func NewService(repository Repository, executor *query.Executor) *Service {
	return &Service{repository: repository, executor: executor}
}

// Save는 쿼리를 실행하고 결과 세트를 저장합니다(실행기를 거쳐 정책·마스킹·감사 적용).
func (s *Service) Save(ctx context.Context, dbSeq, userID int64, admin bool, sqlText string, opts query.Options) (Saved, error) {
	if s.executor == nil {
		return Saved{}, errors.New("SQL 실행기가 구성되지 않았습니다(Master Key 필요)")
	}
	if dbSeq <= 0 || strings.TrimSpace(sqlText) == "" {
		return Saved{}, errors.New("대상 DB와 SQL이 필요합니다")
	}
	opts.Channel = "SAVE"
	result, err := s.executor.Execute(ctx, dbSeq, userID, admin, sqlText, nil, opts)
	if err != nil {
		return Saved{}, err
	}
	encoded, err := json.Marshal(storedResult{Columns: result.Columns, Rows: result.Rows})
	if err != nil {
		return Saved{}, err
	}
	return s.repository.InsertSavedResult(ctx, userID, dbSeq, sqlText, string(encoded), result.RowCount)
}

func (s *Service) List(ctx context.Context, userID int64, admin bool, limit, offset int) (SavedPage, error) {
	if limit <= 0 || limit > 500 {
		limit = 100
	}
	if offset < 0 {
		offset = 0
	}
	items, total, err := s.repository.ListSavedResults(ctx, userID, admin, limit, offset)
	if err != nil {
		return SavedPage{}, err
	}
	return SavedPage{Items: items, Total: total, Limit: limit, Offset: offset}, nil
}

func (s *Service) Get(ctx context.Context, id, userID int64, admin bool) (Detail, error) {
	if id <= 0 {
		return Detail{}, errors.New("결과 ID가 필요합니다")
	}
	meta, resultJSON, err := s.repository.GetSavedResult(ctx, id, userID, admin)
	if err != nil {
		return Detail{}, err
	}
	var stored storedResult
	if resultJSON != "" {
		// 오류를 버리면 깨진 저장본이 "행 0개"인 멀쩡한 결과처럼 보입니다.
		// 사용자는 저장이 원래 비어 있었다고 여기고 원인을 찾을 수 없습니다.
		if err := json.Unmarshal([]byte(resultJSON), &stored); err != nil {
			return Detail{}, fmt.Errorf("저장된 결과를 읽지 못했습니다(저장본이 손상됐을 수 있습니다): %w", err)
		}
	}
	return Detail{Saved: meta, Columns: stored.Columns, Rows: stored.Rows}, nil
}

func (s *Service) Delete(ctx context.Context, id, userID int64, admin bool) error {
	if id <= 0 {
		return errors.New("결과 ID가 필요합니다")
	}
	return s.repository.DeleteSavedResult(ctx, id, userID, admin)
}
// 브라우저용 모듈을 Node 에서 불러오는 공용 로더.
//
// 화면 모듈은 '/js/foo.js' 처럼 브라우저 절대 경로로 서로를 참조합니다. Node 는 그
// 경로를 해석하지 못하므로 파일 URL 로 바꿔 읽습니다. 모듈이 서로를 참조하기
// 시작하면 테스트마다 같은 처리를 하게 되므로 한 곳에 둡니다.
import { readFileSync } from 'node:fs';

const REPO = new URL('../../', import.meta.url);
const ROOT = new URL('internal/webui/js/', REPO);

// repoFile: 저장소 기준 경로를 현재 작업 디렉터리와 무관하게 읽습니다.
//
// 예전에는 테스트들이 readFileSync('internal/webui/js/app.js') 처럼 상대 경로를
// 썼습니다. 저장소 최상위에서 실행할 때만 통했고, 다른 곳에서 부르면 ENOENT 로
// 죽었습니다.
export function repoFile(path) {
  return readFileSync(new URL(path, REPO), 'utf8');
}

export async function loadModule(name) {
  const source = readFileSync(new URL(name, ROOT), 'utf8')
    .replaceAll(/from '\/js\/([\w.-]+)'/g, (_, dep) => `from '${new URL(dep, ROOT).href}'`);
  return import('data:text/javascript;base64,' + Buffer.from(source).toString('base64'));
}
package webui

import (
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// 화면 로직의 상당 부분은 Go 가 아니라 test/js/*.test.mjs 로 검증합니다.
// 그런데 그 파일들을 실행하는 곳이 아무 데도 없었습니다 — CI 도, go test 도.
// 아무도 돌리지 않는 검증은 조용히 썩습니다. 여기서 묶어 두면 `go test ./...`
// 한 번으로 같이 돌고, 세 CI 작업 모두가 이미 그것을 실행합니다.
func TestBrowserModuleTests(t *testing.T) {
	if _, err := exec.LookPath("node"); err != nil {
		t.Skip("node 없음")
	}
	root, err := filepath.Abs("../..")
	if err != nil {
		t.Fatal(err)
	}
	files, err := filepath.Glob(filepath.Join(root, "test", "js", "*.test.mjs"))
	if err != nil {
		t.Fatal(err)
	}
	// 하나도 못 찾으면 경로가 어긋난 것입니다. 조용히 통과시키면 안 됩니다.
	if len(files) == 0 {
		t.Fatal("test/js/*.test.mjs 를 찾지 못했습니다")
	}
	for _, file := range files {
		name := filepath.Base(file)
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			out, err := exec.Command("node", file).CombinedOutput()
			if err != nil {
				// node 의 출력을 함께 남깁니다. 없으면 "exit status 1" 만 보입니다.
				t.Fatalf("%v\n%s", err, strings.TrimSpace(string(out)))
			}
		})
	}
}
